window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-fb6b07953ba1d1ff"]={"versions": [{"id": "FIG-fb6b07953ba1d1ff", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Datenstruktur-Diagramm der AUTOSAR-E2E-Bibliothek (Classic & Adaptive Platform). Es spezifiziert die statische Typdefinition für die Konfiguration des E2E-Profils 6 innerhalb des Namensraums <code>E2E_P06Types</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine Datenstruktur:</p>\n<ul class=\"fig-list\">\n<li><code>«structure» E2E_P06Types::E2E_P06ConfigType</code></li>\n</ul>\n<p class=\"fig-p\">Öffentliche Attribute der Datenstruktur:</p>\n<ul class=\"fig-list\">\n<li><code>+ DataID :uint16</code>: Eindeutige Kennung der geschützten Kommunikationsbeziehung / Datenbotschaft (16 Bit).</li>\n<li><code>+ MaxDataLength :uint16</code>: Maximale zulässige Länge der Nutzdaten inklusive E2E-Header in Bits bzw. Bytes gemäß Profilspezifikation (16 Bit).</li>\n<li><code>+ MaxDeltaCounter :uint8</code>: Maximal erlaubte Differenz zwischen zwei aufeinanderfolgenden Zählerwerten zur Erkennung von Nachrichtenverlust (8 Bit).</li>\n<li><code>+ MinDataLength :uint16</code>: Minimale zulässige Länge der Nutzdaten inklusive E2E-Header (16 Bit).</li>\n<li><code>+ Offset :uint16</code>: Bit- oder Byte-Offset des E2E-Headers innerhalb der geschützten Dateneinheit (16 Bit).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine rein statische Typdefinition dar. Es zeigt keine Verhaltensabläufe, Zustandsübergänge oder Methodenaufrufe.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Spezifikation der Konfigurationsstruktur für E2E Profile 6. Implementierungen der AUTOSAR E2E-Bibliothek müssen diese Strukturmitglieder mit den exakten Typen (<code>uint16</code>, <code>uint8</code>) und Namen bereitstellen. Die Parameter dienen den Profilfunktionen <code>E2E_P06Protect</code> und <code>E2E_P06Check</code> zur Parametrierung der Prüfung und Absicherung von Datenströmen.</p>"}, {"id": "FIG-e12c7efd76f3066f", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Datenstruktur-Diagramm der AUTOSAR-E2E-Bibliothek (Classic & Adaptive Platform). Es spezifiziert die statische Typdefinition für die Konfiguration des E2E-Profils 6 innerhalb des Namensraums <code>E2E::E2E_P06Types</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine Datenstruktur:</p>\n<ul class=\"fig-list\">\n<li><code>«structure» E2E::E2E_P06Types::E2E_P06ConfigType</code></li>\n</ul>\n<p class=\"fig-p\">Öffentliche Attribute der Datenstruktur:</p>\n<ul class=\"fig-list\">\n<li><code>+ DataID :uint16</code>: Eindeutige Kennung der geschützten Kommunikationsbeziehung / Datenbotschaft (16 Bit).</li>\n<li><code>+ MaxDataLength :uint16</code>: Maximale zulässige Länge der Nutzdaten inklusive E2E-Header in Bits bzw. Bytes gemäß Profilspezifikation (16 Bit).</li>\n<li><code>+ MaxDeltaCounter :uint8</code>: Maximal erlaubte Differenz zwischen zwei aufeinanderfolgenden Zählerwerten zur Erkennung von Nachrichtenverlust (8 Bit).</li>\n<li><code>+ MinDataLength :uint16</code>: Minimale zulässige Länge der Nutzdaten inklusive E2E-Header (16 Bit).</li>\n<li><code>+ Offset :uint16</code>: Bit- oder Byte-Offset des E2E-Headers innerhalb der geschützten Dateneinheit (16 Bit).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine rein statische Typdefinition dar. Es zeigt keine Verhaltensabläufe, Zustandsübergänge oder Methodenaufrufe.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Spezifikation der Konfigurationsstruktur für E2E Profile 6. Implementierungen der AUTOSAR E2E-Bibliothek müssen diese Strukturmitglieder mit den exakten Typen (<code>uint16</code>, <code>uint8</code>) und Namen bereitstellen. Die Parameter dienen den Profilfunktionen <code>E2E_P06Protect</code> und <code>E2E_P06Check</code> zur Parametrierung der Prüfung und Absicherung von Datenströmen.</p>"}, {"id": "FIG-2bbda1be4640da74", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Datenstruktur-Diagramm der AUTOSAR-E2E-Bibliothek (Classic & Adaptive Platform). Es spezifiziert die statische Typdefinition für die Konfiguration des E2E-Profils 6 innerhalb des Namensraums <code>E2E_P06Types</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine Datenstruktur:</p>\n<ul class=\"fig-list\">\n<li><code>«structure» E2E_P06Types::E2E_P06ConfigType</code></li>\n</ul>\n<p class=\"fig-p\">Öffentliche Attribute der Datenstruktur:</p>\n<ul class=\"fig-list\">\n<li><code>+ DataID: uint16</code>: Eindeutige Kennung der geschützten Kommunikationsbeziehung / Datenbotschaft (16 Bit).</li>\n<li><code>+ MaxDataLength: uint16</code>: Maximale zulässige Länge der Nutzdaten inklusive E2E-Header in Bits bzw. Bytes gemäß Profilspezifikation (16 Bit).</li>\n<li><code>+ MaxDeltaCounter: uint8</code>: Maximal erlaubte Differenz zwischen zwei aufeinanderfolgenden Zählerwerten zur Erkennung von Nachrichtenverlust (8 Bit).</li>\n<li><code>+ MinDataLength: uint16</code>: Minimale zulässige Länge der Nutzdaten inklusive E2E-Header (16 Bit).</li>\n<li><code>+ Offset: uint16</code>: Bit- oder Byte-Offset des E2E-Headers innerhalb der geschützten Dateneinheit (16 Bit).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine rein statische Typdefinition dar. Es zeigt keine Verhaltensabläufe, Zustandsübergänge oder Methodenaufrufe.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Spezifikation der Konfigurationsstruktur für E2E Profile 6. Implementierungen der AUTOSAR E2E-Bibliothek müssen diese Strukturmitglieder mit den exakten Typen (<code>uint16</code>, <code>uint8</code>) und Namen bereitstellen. Die Parameter dienen den Profilfunktionen <code>E2E_P06Protect</code> und <code>E2E_P06Check</code> zur Parametrierung der Prüfung und Absicherung von Datenströmen.</p>"}], "trans": [{"from": "FIG-fb6b07953ba1d1ff", "to": "FIG-e12c7efd76f3066f", "fr": "R4.2.2", "tr": "R4.3.1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Qualifizierter Paketpfad im Kopf der Struktur von <code>E2E_P06Types::E2E_P06ConfigType</code> auf <code>E2E::E2E_P06Types::E2E_P06ConfigType</code> erweitert.</li>\n</ul>"}, {"from": "FIG-e12c7efd76f3066f", "to": "FIG-2bbda1be4640da74", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Qualifizierter Paketpfad im Kopf der Struktur von <code>E2E::E2E_P06Types::E2E_P06ConfigType</code> auf <code>E2E_P06Types::E2E_P06ConfigType</code> zurückgesetzt.</li>\n<li>Typannotationen der Attribute im Abstand bereinigt (Entfall des Leerzeichens vor dem Doppelpunkt, z. B. <code>+ DataID: uint16</code> statt <code>+ DataID :uint16</code>).</li>\n</ul>"}]};
